+
+/** Walk the task log in reverse to find the most recent PR URL. */
+export function extractPrUrlFromTask(task: Task): string | null {
+  for (let i = task.log.length - 1; i >= 0; i--) {
+    const entry = task.log[i] as Record<string, unknown>;
+    if (entry["action"] === "change_requested" && typeof entry["pr_url"] === "string" && entry["pr_url"]) {
+      return entry["pr_url"] as string;
+    }
+  }
+  if (task.pr?.url) return task.pr.url;
+  return null;
+}
